// Bài 4.1 — Lời chào bằng template literal
function loiChao(ten, tuoi) {
  // Dấu huyền mở template literal; ${...} nhúng giá trị của biến vào đúng chỗ.
  // Khoảng trắng và dấu câu viết thẳng như câu bình thường — không phải nhớ " " + ...
