// Bài 4.1 — == hay ===?
function soSanh(a, b) {
  return {
    kieuA: typeof a,      // vd "string"
    kieuB: typeof b,      // vd "number"
    bangLong: a == b,     // == ĐỔI KIỂU trước khi so ⇒ hay cho kết quả bất ngờ
    bangChat: a === b,    // === so cả giá trị LẪN kiểu ⇒ dễ đoán
  };
}

function anToan(a, b) {
  // Luật của bài học: luôn dùng === (và !==)
  return a === b;
}

